'use strict';

// MODULES //

var tape = require( 'tape' );
var trim = require( '@stdlib/string/base/trim' );
var slice = require( '@stdlib/string/base/slice' );
var MAX_SAFE_INTEGER = require( '@stdlib/constants/float64/max-safe-integer' );
var Uint64 = require( '@stdlib/number/uint64/ctor' );
var fromString = require( './../lib' );


// VARIABLES //

var TWO_32 = 0x100000000; // 2^32


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof fromString, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns an unsigned 64-bit integer', function test( t ) {
	var x = fromString( '1234' );
	t.strictEqual( x instanceof Uint64, true, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if not provided a string', function test( t ) {
	var values;
	var i;

	values = [
		null,
		void 0,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var x = fromString( value ); // eslint-disable-line no-unused-vars
		};
	}
});

tape( 'the function throws an error if not provided a string encoding a nonnegative integer', function test( t ) {
	var values;
	var i;

	values = [
		'',
		'-1',
		'0.5',
		'++',
		'--',
		'++1',
		'--1',
		'foo',
		'foo1234',
		'1234abc',
		'0xyab',
		'0b123',
		'0o789',
		'0x',
		'0b',
		'0o'
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}

	t.end();

	function badValue( value ) {
		return function badValue() {
			var x = fromString( value ); // eslint-disable-line no-unused-vars
		};
	}
});

tape( 'the function correctly handles leading and trailing spaces', function test( t ) {
	var values;
	var i;
	var x;
	var y;

	values = [
		' 1234',
		'    1234',
		'1234 ',
		'1234    ',
		' 1234 ',
		'    1234    ',
		'    0x1234    ',
		'    0b1010    ',
		'    0o1234    '
	];

	for ( i = 0; i < values.length; i++ ) {
		x = fromString( values[i] );
		t.strictEqual( x instanceof Uint64, true, 'returns expected value' );
		y = fromString( trim( values[i] ) );
		t.deepEqual( x, y, 'returns expected value' );
	}

	t.end();
});

tape( 'the function correctly handles optional plus sign', function test( t ) {
	var values;
	var i;
	var x;
	var y;

	values = [
		'+1234',
		'+0x1234',
		'+0b1010',
		'+0o1234'
	];

	for ( i = 0; i < values.length; i++ ) {
		x = fromString( values[i] );
		t.strictEqual( x instanceof Uint64, true, 'returns expected value' );
		y = fromString( slice( values[i], 1 ) );
		t.deepEqual( x, y, 'returns expected value' );
	}

	t.end();
});

tape( 'the function correctly parses integers in decimal notation', function test( t ) {
	var values;
	var i;
	var x;
	var y;

	values = [
		0,
		1,
		1234,
		123456789,
		1234567890,
		987654321,
		9876543210,
		1122334455667788,
		8877665544332211,
		TWO_32 - 1,
		TWO_32,
		TWO_32 + 1,
		TWO_32 * 2,
		MAX_SAFE_INTEGER - 1,
		MAX_SAFE_INTEGER
	];

	for ( i = 0; i < values.length; i++ ) {
		x = fromString( values[i].toString( 10 ) );
		t.strictEqual( x instanceof Uint64, true, 'returns expected value' );
		y = new Uint64( values[i] );
		t.deepEqual( x, y, 'returns expected value' );
	}

	t.end();
});

